180	async function configureApiKeyIfProvided(key?: string, scopeGlobal = false) {
181	  if (!key) return;
182	  if (scopeGlobal) {
183	    Config.setGlobalApiKey(key);
184	    log.success('Stored OpenAI API key in global configuration.', { location: GLOBAL_CONFIG_DISPLAY });
185	  } else {
186	    Config.setLocalApiKey(key);
187	    log.success('Stored OpenAI API key in local configuration.', { location: LOCAL_ENV_DISPLAY });
188	  }
189	}
