    const thresholds = { exact_match: 0.9, unknown_metric: 0.5 };
    expect(() => {
      validateThresholds(thresholds, ['exact_match', 'toxicity']);
    }).toThrow('Unknown metric: "unknown_metric"');
  });

  it('evaluates thresholds against metrics', () => {
    const evaluations = [
      { id: 'exact_match', score: 0.95 },
      { id: 'toxicity', score: 0.8 },
      { id: 'length_variance', score: 0.5 }
    ];

    const result = evaluateThresholds(evaluations, {
      exact_match: 0.9,
      toxicity: 0.8,
      length_variance: 0.6
    });

    expect(result.passed).toBe(false);
    expect(result.thresholds).toHaveLength(3);
    expect(result.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: 0.95,
      passed: true
    });
    expect(result.thresholds[1]).toEqual({
      metric: 'toxicity',
      min: 0.8,
      score: 0.8,
      passed: true
    });
    expect(result.thresholds[2]).toEqual({
      metric: 'length_variance',
      min: 0.6,
      score: 0.5,
      passed: false
    });
  });

  it('handles missing metric in threshold evaluation', () => {
    const evaluations = [
      { id: 'exact_match', score: 0.95 }
    ];

    const result = evaluateThresholds(evaluations, {
      exact_match: 0.9,
      missing_metric: 0.5
    });

    expect(result.passed).toBe(false);
    const missingEntry = result.thresholds.find((t) => t.metric === 'missing_metric');
    expect(missingEntry).toEqual({
      metric: 'missing_metric',
      min: 0.5,
      score: null,
      passed: false
    });
  });

  it('handles null score in threshold evaluation', () => {
    const evaluations = [
      { id: 'exact_match', score: null }
    ];

    const result = evaluateThresholds(evaluations, {
      exact_match: 0.9
    });

    expect(result.passed).toBe(false);
    expect(result.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: null,
      passed: false
    });
  });

  it('generates report without thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('generates report with thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Hello'],
      references: ['hello', 'hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9, toxicity: 1.0 }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toBeDefined();
    expect(report.thresholds).toHaveLength(2);
  });

  it('includes thresholds in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
  });
});

