import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return {};
  }

  const result = {};
  for (const str of thresholdStrings) {
    const match = str.match(/^([a-zA-Z_][a-zA-Z0-9_]*)=(.+)$/);
    if (!match) {
      throw new Error(`Invalid threshold format: "${str}". Expected "<metric>=<number>"`);
    }
    const [, metricId, minStr] = match;
    const min = Number.parseFloat(minStr);
    if (Number.isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Invalid threshold value "${minStr}" for metric "${metricId}". Must be a number between 0 and 1`);
    }
    result[metricId] = min;
  }
  return result;
}

export function validateThresholds(thresholds, availableMetricIds) {
  const thresholdMetrics = Object.keys(thresholds);
  for (const metricId of thresholdMetrics) {
    if (!availableMetricIds.includes(metricId)) {
      const validIds = availableMetricIds.join(', ');
      throw new Error(`Unknown metric: "${metricId}". Valid metrics are: ${validIds}`);
    }
  }
}

export function evaluateThresholds(evaluations, thresholds) {
  const results = [];
  let allPassed = true;

  for (const [metricId, min] of Object.entries(thresholds)) {
    const metric = evaluations.find((m) => m.id === metricId);
    if (!metric) {
      results.push({
        metric: metricId,
        min,
        score: null,
        passed: false
      });
      allPassed = false;
      continue;
    }

    const score = metric.score;
    const passed = score !== null && score >= min;
    if (!passed) {
      allPassed = false;
    }

    results.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }

  return { passed: allPassed, thresholds: results };
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (Object.keys(thresholds).length > 0) {
    const thresholdResults = evaluateThresholds(evaluations, thresholds);

